/**
 * pip-go — type definitions.
 * JSX elements type-check against NativeProps via IntrinsicElements.
 */
import type { NativeProps, NativeTag, VNode, FnComponent, Op, LifecycleName, ListItem, DeviceInfo, ApiResponse } from "./src/types";
import type { ApiResponse as _AR } from "./src/apis";

export type { NativeProps, NativeTag, VNode, FnComponent, Op, LifecycleName, ListItem, DeviceInfo };
export type ApiResponse<T = any> = _AR<T>;

export interface PipGoElementAttributes extends NativeProps {
  key?: string | number;
  children?: any;
}

export interface PipGoIntrinsicElements {
  View: PipGoElementAttributes;
  Text: PipGoElementAttributes;
  Button: PipGoElementAttributes;
  Input: PipGoElementAttributes;
  Image: PipGoElementAttributes;
  Column: PipGoElementAttributes;
  Row: PipGoElementAttributes;
  Card: PipGoElementAttributes;
  Scroll: PipGoElementAttributes;
  List: PipGoElementAttributes;
  Switch: PipGoElementAttributes;
  Checkbox: PipGoElementAttributes;
  Radio: PipGoElementAttributes;
  Progress: PipGoElementAttributes;
  Divider: PipGoElementAttributes;
  WebView: PipGoElementAttributes;
  Dialog: PipGoElementAttributes;
}

export declare function jsx(type: any, props: any, key?: string | number): VNode;
export declare const jsxs: typeof jsx;
export declare const createElement: typeof jsx;
export declare const Fragment: FnComponent;

export declare function useState<S>(initial: S | (() => S)): [S, (next: S | ((prev: S) => S)) => void];
export declare function useReducer<S, A>(reducer: (s: S, a: A) => S, initial: S): [S, (a: A) => void];
export declare function useEffect(effect: () => void | (() => void), deps?: any[]): void;
export declare function useRef<T>(initial: T): { current: T };
export declare function useMemo<T>(factory: () => T, deps: any[]): T;
export declare function useCallback<T extends (...a: any[]) => any>(fn: T, deps: any[]): T;

export interface RequestInit {
  headers?: Record<string, string>;
  timeoutMs?: number;
  signal?: AbortSignal;
}
export declare const api: {
  get<T = any>(url: string, init?: RequestInit): Promise<ApiResponse<T>>;
  post<T = any>(url: string, body?: any, init?: RequestInit): Promise<ApiResponse<T>>;
  put<T = any>(url: string, body?: any, init?: RequestInit): Promise<ApiResponse<T>>;
  delete<T = any>(url: string, init?: RequestInit): Promise<ApiResponse<T>>;
};

export declare function setTimeout(fn: () => void, ms: number): string;
export declare function setInterval(fn: () => void, ms: number): string;
export declare function clearTimeout(id: string): void;
export declare function clearInterval(id: string): void;

export declare const Storage: {
  set(key: string, value: any): boolean;
  get<T = any>(key: string): T | null;
  remove(key: string): boolean;
};

export declare const Device: { getInfo(): DeviceInfo };

export declare const Navigation: {
  register(name: string, component: (props: any) => any): void;
  navigate(name: string, params?: any): void;
  back(): void;
  current(): { name: string; params: any } | null;
  onNavigate(cb: (info: { name: string; params: any }) => void): () => void;
};

export declare function onLifecycle(name: LifecycleName, cb: () => void): () => void;

export declare const App: {
  render(el: any): void;
  on(name: LifecycleName, cb: () => void): () => void;
};

export declare const SDK_VERSION: string;
export declare const View: "View";
export declare const Text: "Text";
export declare const Button: "Button";
export declare const Input: "Input";
export declare const Image: "Image";
export declare const Column: "Column";
